 // opsional: catatan khusus, ketentuan pembayaran, dll.\n  catatan String?\n\n  pembelian        PembelianBahan[]\n  pembayaranHutang PembayaranHutang[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Pembayaran hutang usaha: pelunasan sebagian/total pembelian bahan ke\n// supplier. Setiap pembayaran mengurangi PembelianBahan.belumDibayar.\nmodel PembayaranHutang {\n  id               String         @id @default(cuid())\n  supplierId       String\n  supplier         Supplier       @relation(fields: [supplierId], references: [id])\n  pembelianBahanId String\n  pembelianBahan   PembelianBahan @relation(fields: [pembelianBahanId], references: [id], onDelete: Cascade)\n  jumlah           Decimal        @db.Decimal(14, 2) // nominal yang dibayar\n  tanggal          DateTime       @default(now())\n  catatan          String?\n\n  createdAt DateTime @default(now())\n\n  @@index([supplierId])\n  @@index([pembelianBahanId])\n  @@index([tanggal])\n  @@map(\"pembayaran_hutang\")\n}\n\nmodel Produk {\n  id      String  @id @default(cuid())\n  nama    String\n  sku     String? @unique\n  // Barcode untuk scanner perangkat keras (EAN/UPC/QR internal), opsional\n  barcode String? @unique\n  gambar  String? // URL Cloudinary (secure_url), mis. https://res.cloudinary.com/.../abc123.webp\n  harga   Decimal @db.Decimal(14, 2)\n  stok    Int     @default(0)\n  aktif   Boolean @default(true)\n\n  kategoriId String?\n  kategori   Kategori? @relation(fields: [kategoriId], references: [id])\n\n  resep              ProdukBahan[]\n  item               TransaksiItem[]\n  // Grup modifier yang tersedia untuk produk ini (mode F&B / restoran)\n  produkModifierGrup ProdukModifierGrup[]\n  returItems         ReturItem[]\n  stokOpnameItems    StokOpnameItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([aktif])\n  @@index([kategoriId])\n}\n\n// Resep / BOM: komposisi bahan untuk 1 satuan produk.\n// Stok bahan dikurangi oto